async function openPermission(item){if(!item)return;const[locations,centers]=await Promise.all([api('/api/locations'),api('/api/cost-centers')]),locationItems=locations.locations||[],centerItems=centers.costCenters||[],locAll=item.locationScope?.includes('*'),centerAll=item.costCenterScope?.includes('*');openModal({eyebrow:'PERMISOS OPERATIVOS',title:item.displayName,subtitle:`${item.email} · rol base ${item.role}`,size:'large',body:`<div class="v44-permission-grid">${[['canCreateOrders','Crear pedidos','Puede preparar archivos de compra'],['canEmitOrders','Emitir pedidos','Asigna folio definitivo y publica PDF'],['canReceive','Recepcionar','Registra cantidades, diferencias y evidencia'],['canManageCatalog','Administrar maestros','Productos, categorías, proveedores y centros'],['canViewFinance','Ver finanzas','Pagos, planificación y proyecciones'],['canApprove','Aprobar','Autoriza pedidos sujetos a política']].map(([key,label,help])=>`<label class="v44-check"><input type="checkbox" name="${key}" ${item[key]?'checked':''}><span><strong>${label}</strong><small>${help}</small></span></label>`).join('')}</div><label class="field" style="margin-top:10px"><span>Límite máximo por pedido (CLP, 0 = sin límite)</span><input name="maxOrderAmount" type="number" min="0" step="1000" value="${Number(item.maxOrderAmount||0)}"></label><div class="v44-grid" style="margin-top:10px"><section class="v44-panel"><h3>Locales</h3><label class="v44-check"><input type="checkbox" id="v44AllLocations" ${locAll?'checked':''}><span><strong>Todos los locales</strong><small>Ignora selección individual</small></span></label><div class="v44-list" style="margin-top:6px">${locationItems.map(loc=>`<label class="v44-check"><input type="checkbox" data-v44-location value="${esc(loc.id)}" ${locAll||item.locationScope?.includes(loc.id)?'checked':''}><span><strong>${esc(loc.name)}</strong></span></label>`).join('')}</div></section><section class="v44-panel"><h3>Centros de costo</h3><label class="v44-check"><input type="checkbox" id="v44AllCenters" ${centerAll?'checked':''}><span><strong>Todos los centros</strong><small>Ignora selección individual</small></span></label><div class="v44-list" style="margin-top:6px">${centerItems.map(center=>`<label class="v44-check"><input type="checkbox" data-v44-center value="${esc(center.id)}" ${centerAll||item.costCenterScope?.includes(center.id)?'checked':''}><span><strong>${esc(center.name)}</strong><small>${esc(center.locationName||'')}</small></span></label>`).join('')}</div></section></div>`,submitLabel:'Guardar permisos',onSubmit:async form=>{const locationScope=$('#v44AllLocations').checked?['*']:$$('[data-v44-location]:checked').map(input=>input.value),costCenterScope=$('#v44AllCenters').checked?['*']:$$('[data-v44-center]:checked').map(input=>input.value);if(!locationScope.length||!costCenterScope.length)throw new Error('Debes dejar al menos un local y un centro habilitado');const json={locationScope,costCenterScope,maxOrderAmount:Number(form.get('maxOrderAmount')||0),canCreateOrders:form.get('canCreateOrders')==='on',canEmitOrders:form.get('canEmitOrders')==='on',canReceive:form.get('canReceive')==='on',canManageCatalog:form.get('canManageCatalog')==='on',canViewFinance:form.get('canViewFinance')==='on',canApprove:form.get('canApprove')==='on'};await api(`/api/permissions-v44/${encodeURIComponent(item.userId)}`,{method:'PUT',json});toast('Permisos actualizados');closeModal();loadPermissions()}});$('#v44AllLocations').onchange=()=>$$('[data-v44-location]').forEach(input=>input.checked=$('#v44AllLocations').checked||input.checked);$('#v44AllCenters').onchange=()=>$$('[data-v44-center]').forEach(input=>input.checked=$('#v44AllCenters').checked||input.checked)}

async function renderSystemV44(){setPage('system','OBSERVABILIDAD','Salud del sistema');if(!roleAdmin())return $('#mainContent').innerHTML='<div class="v44-empty"><h3>Acceso restringido</h3></div>';$('#mainContent').innerHTML=`<section class="v44-page"><header class="v44-head"><div><span class="eyebrow">OPERACIÓN Y CONFIABILIDAD</span><h2>Salud del sistema</h2><p>D1, R2, errores del cliente, PDFs faltantes, cotejos pendientes, sincronización y trabajos procesables desde un solo lugar.</p></div><div class="v44-head-actions"><button class="btn" id="v44HealthSnapshot">Guardar diagnóstico</button><button class="btn primary" id="v44HealthReload">Actualizar</button></div></header><div id="v44SystemBody">${skeleton(7)}</div></section>`;$('#v44HealthReload').onclick=loadSystem;$('#v44HealthSnapshot').onclick=async()=>{await api('/api/system-health-v44/snapshot',{method:'POST',json:{}});toast('Diagnóstico guardado')};await loadSystem()}
async function loadSystem(){const host=$('#v44SystemBody');if(!host)return;host.innerHTML=skeleton(6);try{const[healthPayload,jobsPayload]=await Promise.all([api('/api/system-health-v44',{fresh:true}),api('/api/jobs-v44',{fresh:true})]),h=healthPayload.health||{},jobs=jobsPayload.jobs||[];host.innerHTML=`<section class="v44-health-grid"><article class="v44-health"><span>D1</span><strong>${h.database==='ready'?'Operativo':'Revisar'}</strong><small>${h.serverProbeMs} ms de sonda</small></article><article class="v44-health"><span>R2</span><strong>${h.r2?'Operativo':'No disponible'}</strong><small>almacenamiento documental</small></article><article class="v44-health"><span>Pedidos sin PDF</span><strong>${h.ordersMissingPdf}</strong><small>requieren regeneración</small></article><article class="v44-health"><span>Líneas sin cotejar</span><strong>${h.unmatchedInvoiceLines}</strong><small>revisión de factura</small></article></section><section class="v44-grid"><article class="v44-panel"><h3>Eventos del cliente · 24 h</h3><div class="v44-list">${(h.clientEvents24h||[]).map(item=>`<div class="v44-row"><span class="v44-state ${/error|fail|timeout/i.test(item.type)?'danger':'warn'}">${item.total}</span><div><strong>${esc(item.type)}</strong><small>${item.lastAt?new Date(item.lastAt).toLocaleString('es-CL'):''}</small></div></div>`).join('')||'<div class="v44-empty">Sin errores recientes.</div>'}</div></article><article class="v44-panel"><h3>Sincronización</h3><div class="v44-list">${Object.entries(h.sync||{}).map(([status,total])=>`<div class="v44-row"><span class="v44-state ${status==='failed'?'danger':status==='pending'?'warn':'ok'}">${total}</span><div><strong>${esc(status)}</strong><small>mutaciones persistentes</small></div></div>`).join('')||'<div class="v44-empty">Sin mutaciones pendientes.</div>'}</div></article><article class="v44-panel full"><div class="v44-head" style="align-items:center"><div><h3>Cola de trabajos</h3><p>PDF, IA, conciliación, salud y recálculos con estado y reintento.</p></div><div class="v44-head-actions"><button class="btn small" id="v44QueueHealth">Encolar diagnóstico</button><button class="btn small" id="v44QueueSuppliers">Recalcular proveedores</button></div></div><div class="v44-list" style="margin-top:9px">${jobs.map(job=>`<article class="v44-row v44-job"><span class="v44-job-icon">${job.status==='completed'?'✓':job.status==='failed'?'!':'↻'}</span><div><strong>${esc(job.jobType)}</strong><small>${esc(job.entityType||'sistema')} ${esc(job.entityId||'')} · intento ${job.attempts}/${job.maxAttempts}${job.errorMessage?` · ${esc(job.errorMessage)}`:''}</small><div class="v44-progress" style="margin-top:5px"><i style="width:${clamp(job.progress,0,100)}%"></i></div></div><div class="v44-row-actions"><span class="v44-state ${job.status==='failed'?'danger':job.status==='completed'?'ok':'warn'}">${esc(job.status)}</span>${job.status==='failed'?`<button class="btn small" data-v44-job-retry="${esc(job.id)}">Reintentar</button>`:''}${job.status==='pending'?`<button class="btn small" data-v44-job-run="${esc(job.id)}">Procesar</button>`:''}</div></article>`).join('')||'<div class="v44-empty">No hay trabajos registrados.</div>'}</div></article></section>`;$$('[data-v44-job-retry]').forEach(button=>button.onclick=()=>jobAction(button.dataset.v44JobRetry,'retry'));$$('[data-v44-job-run]').forEach(button=>button.onclick=()=>jobAction(button.dataset.v44JobRun,'run'));$('#v44QueueHealth').onclick=()=>queueJob('health_snapshot');$('#v44QueueSuppliers').onclick=()=>queueJob('supplier_metrics_refresh')}catch(error){host.innerHTML=`<div class="v44-empty"><h3>No se pudo cargar salud del sistema</h3><p>${esc(error.message)}</p></div>`}}
async function queueJob(jobType){await api('/api/jobs-v44',{method:'POST',json:{jobType}});toast('Trabajo encolado');loadSystem()}
