function enhanceNavigation(){const nav=$('.side-nav[aria-label="Navegación principal"]');if(nav&&!nav.dataset.v44){nav.dataset.v44='1';const operations=nav.querySelector('[data-view="operations"]');operations?.insertAdjacentHTML('afterend',navLink('masterdata','Maestro de datos','▦'));const finance=nav.querySelector('[data-view="finance"]');finance?.insertAdjacentHTML('afterend',navLink('planning','Planificación','⌁')+navLink('intelligence','Inteligencia','⌁'));const audit=nav.querySelector('[data-view="audit"]');if(audit&&roleAdmin())audit.insertAdjacentHTML('afterend',navLink('permissions','Permisos','◎')+navLink('system','Salud del sistema','◉'))}
  const sheet=$('.v43-more-sheet');if(sheet&&!sheet.dataset.v44){sheet.dataset.v44='1';const groups=[...sheet.querySelectorAll('.v43-more-group')],find=text=>groups.find(group=>normalize(group.querySelector(':scope>span')?.textContent).includes(normalize(text)));find('Gestión')?.insertAdjacentHTML('beforeend',moreItem('intelligence','Inteligencia','Precios y proveedores','⌁')+moreItem('planning','Planificación','Presupuesto y caja','$'));find('Datos maestros')?.insertAdjacentHTML('beforeend',moreItem('masterdata','Maestro de datos','Ciclo de vida y edición masiva','▦'));if(roleAdmin())find('Administración')?.insertAdjacentHTML('beforeend',moreItem('permissions','Permisos','Alcances y límites','◎')+moreItem('system','Salud del sistema','Errores, R2, D1 y trabajos','◉'));sheet.querySelectorAll('[data-v44-go]').forEach(button=>button.onclick=()=>{document.querySelector('.v43-more-backdrop')?.remove();sheet.remove();openRoute(button.dataset.v44Go)})}}
