function closeSearch(){document.querySelector('.v44-search-overlay')?.remove()}
function installGlobalSearch(){const old=$('#globalSearch');if(!old||old.dataset.v44)return;const input=old.cloneNode(true);input.dataset.v44='1';input.dataset.v41='1';old.replaceWith(input);const open=()=>{document.querySelector('#commandMenu')?.classList.add('hidden');renderSearch([],'Escribe al menos 2 caracteres')};input.addEventListener('focus',open);input.addEventListener('input',()=>{clearTimeout(searchTimer);const q=input.value.trim();if(q.length<2){renderSearch([],'Escribe al menos 2 caracteres');return}searchTimer=setTimeout(()=>searchV44(q),180)});input.addEventListener('keydown',event=>{if(event.key==='Escape'){closeSearch();input.blur()}});document.addEventListener('pointerdown',event=>{if(!event.target.closest('.v44-search-overlay,.global-search'))closeSearch()})}
async function searchV44(q){try{const payload=await api(`/api/global-search-v44?q=${encodeURIComponent(q)}`,{fresh:true,timeout:15000}),results=payload.results||[];renderSearch(results,results.length?'':'Sin resultados')}catch(error){renderSearch([],error.message)}}
function renderSearch(results,message=''){let panel=$('.v44-search-overlay');if(!panel){panel=document.createElement('section');panel.className='v44-search-overlay';panel.setAttribute('role','listbox');document.body.append(panel)}if(!results.length){panel.innerHTML=`<div class="v44-empty">${esc(message)}</div>`;return}const icons={order:'▤',product:'◫',supplier:'◇',invoice:'▧',category:'▦','cost-center':'◎',user:'●'},labels={order:'Pedidos',product:'Productos',supplier:'Proveedores',invoice:'Facturas',category:'Categorías','cost-center':'Centros de costo',user:'Usuarios'},groups=new Map();for(const item of results){if(!groups.has(item.kind))groups.set(item.kind,[]);groups.get(item.kind).push(item)}panel.innerHTML=[...groups].map(([kind,items])=>`<div class="v44-search-group"><span>${labels[kind]||kind}</span>${items.map(item=>`<button class="v44-search-item" type="button" data-v44-search-kind="${esc(kind)}" data-v44-search-id="${esc(item.id)}" data-v44-search-view="${esc(item.view||'')}" data-v44-search-entity="${esc(item.entity||'')}"><i>${icons[kind]||'⌕'}</i><span><strong>${esc(item.title)}</strong><small>${esc(item.subtitle||'')}</small></span><b>›</b></button>`).join('')}</div>`).join('');panel.querySelectorAll('[data-v44-search-kind]').forEach(button=>button.onclick=()=>openSearchResult(button))}
function openSearchResult(button){const kind=button.dataset.v44SearchKind,id=button.dataset.v44SearchId;closeSearch();$('#globalSearch').value='';haptic();if(kind==='order')return openOrderDetail(id);if(['product','supplier','category','cost-center'].includes(kind)){const entity=button.dataset.v44SearchEntity||({product:'products',supplier:'suppliers',category:'categories','cost-center':'cost-centers'}[kind]);sessionStorage.setItem('nuvasto:v44:master-focus',JSON.stringify({entity,id,q:''}));return openRoute('masterdata')}if(kind==='user')return openRoute('permissions');if(kind==='invoice')return openRoute('documents');return openRoute(button.dataset.v44SearchView||'dashboard')}

let assistCache=new Map();
async function enhanceMasterList(){if($('#modalTitle')?.textContent.trim()!=='Lista maestra')return;const builder=$('.order-file-builder'),center=$('#orderFileCenter'),toolbar=$('.order-file-toolbar');if(!builder||!center||!toolbar)return;if(!$('#v44MasterAssist'))toolbar.insertAdjacentHTML('afterend','<section class="v44-master-assist" id="v44MasterAssist"><div class="v44-master-assist-head"><div><strong>Accesos rápidos</strong><small id="v44AssistHint" style="display:block;color:var(--muted);margin-top:2px">Cargando uso reciente…</small></div><button class="btn small" id="v44ApplyLastOrder" type="button">Copiar último pedido</button></div><div class="v44-master-modes"><button class="v44-master-mode active" data-v44-master-mode="all">Todos</button><button class="v44-master-mode" data-v44-master-mode="favorites">★ Favoritos</button><button class="v44-master-mode" data-v44-master-mode="frequent">Frecuentes</button><button class="v44-master-mode" data-v44-master-mode="recent">Pedido anterior</button><button class="v44-master-mode" data-v44-master-mode="templates">Plantillas</button></div></section>');if(center.dataset.v44Assist!=='1'){center.dataset.v44Assist='1';center.addEventListener('change',()=>setTimeout(loadMasterAssist,80))}await loadMasterAssist();decorateMasterRows()}
async function loadMasterAssist(){const centerId=$('#orderFileCenter')?.value,host=$('#v44MasterAssist');if(!centerId||!host)return;try{let assist=assistCache.get(centerId);if(!assist){assist=(await api(`/api/master-list-assist-v44?costCenterId=${encodeURIComponent(centerId)}`,{fresh:true,timeout:25000})).assist;assistCache.set(centerId,assist)}host.dataset.centerId=centerId;host._assist=assist;$('#v44AssistHint').textContent=`${assist.favorites.length} favoritos · ${assist.usage.length} productos con uso reciente${assist.suggestedTemplateId?' · plantilla sugerida disponible':''}`;$('#v44ApplyLastOrder').disabled=!assist.lastOrder;$('#v44ApplyLastOrder').onclick=()=>applyOrderItems(assist.lastOrder?.items||[]);$$('[data-v44-master-mode]').forEach(button=>button.onclick=()=>{const mode=button.dataset.v44MasterMode;$$('[data-v44-master-mode]').forEach(item=>item.classList.toggle('active',item===button));if(mode==='templates')return openTemplates(assist);filterMasterRows(mode,assist)});decorateMasterRows()}catch(error){$('#v44AssistHint').textContent='No se pudieron cargar accesos rápidos'}}
function decorateMasterRows(){const assist=$('#v44MasterAssist')?._assist;if(!assist)return;const favoriteSet=new Set(assist.favorites||[]);for(const row of $$('#orderFileProducts [data-order-product]')){const product=row.dataset.orderProduct,copy=row.querySelector('.order-file-product');if(copy&&!copy.querySelector('.v44-favorite'))copy.insertAdjacentHTML('beforeend',`<button class="v44-favorite ${favoriteSet.has(product)?'active':''}" type="button" data-v44-favorite="${esc(product)}" aria-label="${favoriteSet.has(product)?'Quitar de favoritos':'Agregar a favoritos'}">★</button>`)}$$('[data-v44-favorite]').forEach(button=>{if(button.dataset.bound)return;button.dataset.bound='1';button.onclick=async event=>{event.preventDefault();event.stopPropagation();const active=button.classList.toggle('active'),centerId=$('#orderFileCenter').value;try{await api(`/api/master-list-favorites-v44/${encodeURIComponent(button.dataset.v44Favorite)}`,{method:'PATCH',json:{costCenterId,favorite:active}});assistCache.delete(centerId);haptic()}catch(error){button.classList.toggle('active');toast(error.message,'error')}}})}
function filterMasterRows(mode,assist){const favorites=new Set(assist.favorites||[]),frequent=new Set((assist.usage||[]).slice(0,40).map(item=>item.productId)),recent=new Set((assist.lastOrder?.items||[]).map(item=>item.productId));for(const row of $$('#orderFileProducts [data-order-product]')){const id=row.dataset.orderProduct,visible=mode==='all'||(mode==='favorites'&&favorites.has(id))||(mode==='frequent'&&frequent.has(id))||(mode==='recent'&&recent.has(id));row.classList.toggle('v44-assist-hidden',!visible)}for(const category of $$('#orderFileProducts .order-file-category'))category.classList.toggle('v44-assist-hidden',![...category.querySelectorAll('.order-file-row')].some(row=>!row.classList.contains('v44-assist-hidden')));for(const warehouse of $$('#orderFileProducts .order-file-warehouse'))warehouse.classList.toggle('v44-assist-hidden',![...warehouse.querySelectorAll('.order-file-category')].some(section=>!section.classList.contains('v44-assist-hidden')))}
function applyOrderItems(items){let count=0;const map=new Map((items||[]).map(item=>[String(item.productId||item.product_id||item.id||''),item]));for(const row of $$('#orderFileProducts [data-order-product]')){const item=map.get(row.dataset.orderProduct);if(!item)continue;const input=row.querySelector('[data-core-quantity]');if(!input)continue;input.value=String(item.quantity??item.qty??item.quantityOrdered??'');input.dispatchEvent(new Event('input',{bubbles:true}));const unit=row.querySelector('[data-order-unit]'),unitValue=item.unit||item.orderUnit||item.order_unit;if(unit&&unitValue&&[...unit.options].some(option=>option.value===unitValue)){unit.value=unitValue;unit.dispatchEvent(new Event('change',{bubbles:true}))}count++}toast(`${count} productos cargados`);haptic()}
function openTemplates(assist){const templates=assist.templates||[];if(!templates.length)return toast('No hay plantillas guardadas para este centro','error');openModal({eyebrow:'PLANTILLAS',title:'Cargar pedido recurrente',subtitle:'Aplica cantidades guardadas y luego ajusta solo lo necesario.',hideSubmit:true,body:`<div class="v44-list">${templates.map(item=>`<button class="v44-row" type="button" data-v44-template="${esc(item.id)}"><span class="v44-state ${item.id===assist.suggestedTemplateId?'ok':''}">${item.id===assist.suggestedTemplateId?'Sugerida':'Plantilla'}</span><div><strong>${esc(item.name)}</strong><small>${item.items.length} productos · ${esc(item.triggerType)}</small></div><b>›</b></button>`).join('')}</div>`});$$('[data-v44-template]').forEach(button=>button.onclick=()=>{const item=templates.find(template=>template.id===button.dataset.v44Template);closeModal();applyOrderItems(item?.items||[])})}

function enhanceReceiving(){for(const button of $$('[data-v41-receive]')){if(button.dataset.v44Capture)return;button.dataset.v44Capture='1';button.addEventListener('click',()=>{currentReceptionOrderId=button.dataset.v41Receive},{capture:true})}if($('#modalEyebrow')?.textContent.trim()!=='RECEPCIÓN PROFESIONAL'||!currentReceptionOrderId)return;const body=$('#modalBody');if(!body||body.querySelector('#v44ReceiveTools'))return;const summary=body.querySelector('.v41-receive-summary');summary?.insertAdjacentHTML('afterend','<section class="v44-receive-tools" id="v44ReceiveTools"><button class="btn small" type="button" id="v44ScanProduct">▦ Escanear producto</button><button class="btn small" type="button" id="v44AddEvidence">＋ Foto / evidencia</button><button class="btn small" type="button" id="v44EvidenceHistory">Ver evidencia</button><div class="v44-evidence-list" id="v44EvidenceChips"></div><input class="hidden" id="v44EvidenceInput" type="file" accept="image/*,.pdf" capture="environment"></section>');$('#v44ScanProduct').onclick=()=>startScanner(currentReceptionOrderId);$('#v44AddEvidence').onclick=()=>$('#v44EvidenceInput').click();$('#v44EvidenceInput').onchange=uploadEvidence;$('#v44EvidenceHistory').onclick=showEvidence;loadEvidenceChips()}
async function uploadEvidence(){const file=$('#v44EvidenceInput')?.files?.[0];if(!file)return;const form=new FormData();form.append('file',file,file.name);const button=$('#v44AddEvidence');button.disabled=true;button.textContent='Subiendo…';try{const stored=await api('/api/files?purpose=reception-evidence',{method:'POST',body:form,timeout:90000}),note=prompt('Observación de esta evidencia (opcional)')||'';await api('/api/reception-evidence-v44',{method:'POST',json:{orderId:currentReceptionOrderId,fileId:stored.file?.id||'',storageKey:stored.file?.key||'',evidenceType:file.type.startsWith('image/')?'photo':'document',note}});toast('Evidencia asociada al pedido');haptic();loadEvidenceChips()}catch(error){toast(error.message,'error')}finally{button.disabled=false;button.textContent='＋ Foto / evidencia';$('#v44EvidenceInput').value=''}}
async function loadEvidenceChips(){try{const payload=await api(`/api/reception-evidence-v44?orderId=${encodeURIComponent(currentReceptionOrderId)}`,{fresh:true}),items=payload.evidence||[],host=$('#v44EvidenceChips');if(host)host.innerHTML=items.slice(0,3).map(item=>`<span class="v44-evidence-chip">${item.evidenceType==='photo'?'Foto':'Doc'} ✓</span>`).join('')}catch{}}
async function showEvidence(){try{const payload=await api(`/api/reception-evidence-v44?orderId=${encodeURIComponent(currentReceptionOrderId)}`,{fresh:true}),items=payload.evidence||[];openModal({eyebrow:'EVIDENCIA DE RECEPCIÓN',title:`${items.length} archivo${items.length===1?'':'s'} asociado${items.length===1?'':'s'}`,hideSubmit:true,body:`<div class="v44-list">${items.map(item=>`<article class="v44-row"><span class="v44-state ok">${esc(item.evidenceType)}</span><div><strong>${esc(item.note||'Sin observación')}</strong><small>${item.createdAt?new Date(item.createdAt).toLocaleString('es-CL'):''} · ${esc(item.createdBy||'')}</small></div>${item.storageKey?`<button class="btn small" data-v44-open-evidence="${esc(item.storageKey)}">Abrir</button>`:''}</article>`).join('')||'<div class="v44-empty">Sin evidencia asociada.</div>'}</div>`});$$('[data-v44-open-evidence]').forEach(button=>button.onclick=()=>window.open(`/api/files/${encodeURIComponent(button.dataset.v44OpenEvidence)}`,'_blank'))}catch(error){toast(error.message,'error')}}
async function startScanner(orderId){const order=(await api(`/api/orders/${encodeURIComponent(orderId)}`,{fresh:true})).order,products=state.cache.products?.length?state.cache.products:(await api('/api/products')).products||[],productById=new Map(products.map(item=>[item.id,item])),itemByBarcode=new Map();for(const item of order.items||[]){const product=productById.get(item.productId);if(product?.barcode)itemByBarcode.set(String(product.barcode),item)}const pick=code=>{const item=itemByBarcode.get(String(code||''));if(!item){toast(`Código ${code} no está en este pedido`,'error');return false}const row=$(`[data-v41-line="${CSS.escape(String(item.id))}"]`);if(!row){toast('El producto ya no está pendiente','error');return false}row.scrollIntoView({behavior:'smooth',block:'center'});const accepted=row.querySelector('[name=accepted]');accepted?.focus();accepted?.select();haptic();return true};if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){const code=prompt('Escanea o escribe el código de barras');if(code)pick(code);return}let stream=null,overlay=document.createElement('div');overlay.className='v44-scanner';overlay.innerHTML='<section class="v44-scanner-card"><video autoplay playsinline muted></video><div class="v44-scanner-actions"><button class="btn" type="button" data-v44-scan-close>Cerrar</button><button class="btn" type="button" data-v44-manual-code>Ingresar código</button></div></section>';document.body.append(overlay);const stop=()=>{stream?.getTracks?.().forEach(track=>track.stop());overlay.remove()};overlay.querySelector('[data-v44-scan-close]').onclick=stop;overlay.querySelector('[data-v44-manual-code]').onclick=()=>{const code=prompt('Código de barras');if(code&&pick(code))stop()};try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=overlay.querySelector('video');video.srcObject=stream;const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e','code_128','qr_code']});let running=true;const scan=async()=>{if(!overlay.isConnected||!running)return;try{const codes=await detector.detect(video);if(codes[0]?.rawValue&&pick(codes[0].rawValue)){running=false;stop();return}}catch{}setTimeout(scan,260)};video.onloadeddata=scan}catch(error){stop();const code=prompt('No fue posible abrir la cámara. Ingresa el código manualmente.');if(code)pick(code)}}

function enhanceOnboarding(){if(state.view!=='dashboard'||localStorage.getItem('nuvasto:v44:onboarded')==='1'||$('#v44Onboarding'))return;const root=$('#mainContent>section');if(!root)return;root.insertAdjacentHTML('afterbegin','<section class="v44-onboarding" id="v44Onboarding"><div><h3>Nuvasto Procurement OS está listo</h3><p>Usa Lista Maestra para comprar, Maestro de datos para mantener la base, Inteligencia para comparar proveedores y Salud del sistema para diagnosticar problemas.</p></div><div class="v44-onboarding-actions"><button class="btn small" id="v44InstallPwa">Instalar PWA</button><button class="btn small" id="v44DismissOnboarding">Entendido</button></div></section>');$('#v44InstallPwa').classList.toggle('hidden',!installEvent);$('#v44InstallPwa').onclick=async()=>{if(!installEvent)return toast('Usa “Agregar a pantalla de inicio” desde el menú del navegador.');await installEvent.prompt();await installEvent.userChoice.catch(()=>{});installEvent=null;$('#v44InstallPwa')?.classList.add('hidden')};$('#v44DismissOnboarding').onclick=()=>{localStorage.setItem('nuvasto:v44:onboarded','1');$('#v44Onboarding').remove()}}

function scheduleEnhance(){if(enhanceQueued)return;enhanceQueued=true;requestAnimationFrame(()=>{enhanceQueued=false;enhanceNavigation();installGlobalSearch();enhanceMasterList().catch(()=>{});enhanceReceiving();enhanceOnboarding()})}
export function initializeProcurementOSV44(){if(initialized)return;initialized=true;injectStyles();registerRouteRenderer('masterdata',renderMasterDataV44);registerRouteRenderer('intelligence',renderIntelligenceV44);registerRouteRenderer('planning',renderPlanningV44);registerRouteRenderer('permissions',renderPermissionsV44);registerRouteRenderer('system',renderSystemV44);window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installEvent=event;enhanceOnboarding()});window.addEventListener('pedidos:view-rendered',scheduleEnhance);new MutationObserver(records=>{if(records.some(record=>record.addedNodes.length))scheduleEnhance()}).observe(document.body,{subtree:true,childList:true});setTimeout(scheduleEnhance,450);window.NuvastoProcurementOSV44=Object.freeze({version:VERSION,renderMasterDataV44,renderIntelligenceV44,renderPlanningV44,renderSystemV44})}
